using System;using System.IO;using System.Linq;using System.Text;using System.Xml;using System.Xml.Linq;using System.Collections.Generic;using System.Globalization;using System.Diagnostics;using System.Runtime.InteropServices;
namespace V15Voice {
public sealed class SubtitleCue {public double Start,End;public string Text="",Note="",Info="";public bool Reviewed;}
public sealed class SubtitleDocument {
 public double Duration;public string Device="",Model="",Pipeline="v1410-speech-1",Repetitions="preserve";public XElement Audit,WordTimings;public int ReviewCount{get{return Cues.Count(c=>!c.Reviewed&&!String.IsNullOrEmpty(c.Note));}}public string CompletionState{get{return ReviewCount>0?"Đã xuất · cần duyệt ("+ReviewCount+")":"Xong";}}public List<SubtitleCue> Cues=new List<SubtitleCue>();
 static double Number(XElement x,string key){double n;if(!double.TryParse((string)x.Attribute(key),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||Double.IsNaN(n)||Double.IsInfinity(n))throw new IOException("Mốc phụ đề không hợp lệ.");return n;}
 public static SubtitleDocument Load(string file){var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=64*1024*1024};XElement x;using(var r=XmlReader.Create(file,settings))x=XElement.Load(r);if(x.Name!="subtitles")throw new IOException("Không đúng dữ liệu phụ đề.");var d=new SubtitleDocument{Duration=Number(x,"duration"),Device=(string)x.Attribute("device")??"",Model=(string)x.Attribute("model")??"",Pipeline=(string)x.Attribute("pipeline")??"",Repetitions=(string)x.Attribute("repetitions")??"preserve",Audit=x.Element("audit")==null?null:new XElement(x.Element("audit")),WordTimings=x.Element("words")==null?null:new XElement(x.Element("words"))};foreach(var c in x.Elements("cue"))d.Cues.Add(new SubtitleCue{Start=Number(c,"start"),End=Number(c,"end"),Text=c.Value,Note=(string)c.Attribute("note")??"",Info=(string)c.Attribute("info")??"",Reviewed=(string)c.Attribute("reviewed")=="true"});d.Validate();return d;}
 public void Validate(){if(Duration<=0||Double.IsNaN(Duration)||Double.IsInfinity(Duration)||Cues.Count==0)throw new IOException("Không có phụ đề hoặc thời lượng hợp lệ.");double end=0;foreach(var c in Cues){if(Double.IsNaN(c.Start)||Double.IsNaN(c.End)||Double.IsInfinity(c.Start)||Double.IsInfinity(c.End)||c.Start<0||c.Start<end-.0005||c.End>Duration+.0005||Math.Round(c.End*1000)<=Math.Round(c.Start*1000)||String.IsNullOrWhiteSpace(c.Text)||c.Text.Contains("-->"))throw new IOException("Phụ đề có mốc chồng nhau, thiếu lời hoặc vượt thời lượng. Kiểm tra bảng trước khi xuất.");end=c.End;}}
 public void Save(string path){Validate();var x=new XElement("subtitles",new XAttribute("version","1.4.10"),new XAttribute("pipeline",Pipeline??""),new XAttribute("repetitions",Repetitions??"preserve"),new XAttribute("duration",Duration.ToString("R",CultureInfo.InvariantCulture)),new XAttribute("device",Device),new XAttribute("model",Model));foreach(var c in Cues)x.Add(new XElement("cue",new XAttribute("start",c.Start.ToString("R",CultureInfo.InvariantCulture)),new XAttribute("end",c.End.ToString("R",CultureInfo.InvariantCulture)),new XAttribute("note",c.Note??""),new XAttribute("info",c.Info??""),new XAttribute("reviewed",c.Reviewed?"true":"false"),c.Text));if(Audit!=null)x.Add(new XElement(Audit));if(WordTimings!=null)x.Add(new XElement(WordTimings));string tmp=path+".tmp";x.Save(tmp);if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
 public static string Stamp(double seconds){long ms=(long)Math.Round(seconds*1000);return (ms/3600000).ToString("00")+":"+(ms/60000%60).ToString("00")+":"+(ms/1000%60).ToString("00")+","+(ms%1000).ToString("000");}
 public static double ParseTime(string text){var m=System.Text.RegularExpressions.Regex.Match(text??"",@"^(\d+):([0-5]\d):([0-5]\d)[,.](\d{3})$");if(!m.Success)throw new FormatException("Nhập mốc dạng 00:00:01,250.");double n=double.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture)*3600+int.Parse(m.Groups[2].Value)*60+int.Parse(m.Groups[3].Value)+int.Parse(m.Groups[4].Value)/1000.0;if(Double.IsInfinity(n))throw new FormatException("Mốc quá lớn.");return n;}
 public string ExportBeside(string media){Validate();string stem=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(media)),Path.GetFileNameWithoutExtension(media));var b=new StringBuilder();for(int i=0;i<Cues.Count;i++){var c=Cues[i];string text=System.Text.RegularExpressions.Regex.Replace(c.Text.Replace("\r\n","\n").Replace('\r','\n').Trim(),@"\n\s*\n","\n");b.Append(i+1).Append("\r\n").Append(Stamp(c.Start)).Append(" --> ").Append(Stamp(c.End)).Append("\r\n").Append(text).Append("\r\n\r\n");}for(int i=0;i<10000;i++){string path=stem+(i==0?"":"_"+(i+1))+".srt";FileStream output;try{output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None);}catch(IOException){if(File.Exists(path))continue;throw;}try{using(output)using(var writer=new StreamWriter(output,new UTF8Encoding(false)))writer.Write(b.ToString());return path;}catch{try{File.Delete(path);}catch{}throw;}}throw new IOException("Quá nhiều SRT trùng tên.");}
}
public sealed class SubtitleJob {public string Input="",Result="",Output="",State="Chờ",Error="",Reference="",SourceStamp="",Profile="";public int Track;public SubtitleDocument Document;}
public sealed class SubtitleProcess:IDisposable {
 Process process;volatile bool cancelled;IntPtr job=IntPtr.Zero;readonly object gate=new object();public bool Cancelled{get{return cancelled;}}
 public void Run(string python,string script,string args,Action<int,string> notify){
  if(cancelled)throw new OperationCanceledException();string errors="",lastMessage="Đang khởi động bộ phụ đề";int lastProgress=0;
  string boot="import os,runpy,sys;sys.path.insert(0,os.path.dirname(os.path.abspath(sys.argv[1])));sys.argv=sys.argv[1:];runpy.run_path(sys.argv[0],run_name='__main__')";
  var pi=new ProcessStartInfo(python,"-c "+KokoroEngine.Q(boot)+" "+KokoroEngine.Q(script)+" "+args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=Path.GetDirectoryName(script)};pi.EnvironmentVariables["PYTHONNOUSERSITE"]="1";pi.EnvironmentVariables["PYTHONIOENCODING"]="utf-8";
  using(var p=new Process{StartInfo=pi}){p.OutputDataReceived+=(s,e)=>{if(e.Data==null)return;string[] a=e.Data.Split('\t');int n;if(a.Length==3&&a[0]=="V15_ASR"&&int.TryParse(a[1],out n))try{lastProgress=Math.Max(0,Math.Min(100,n));lastMessage=ExternalSpeech.Decode(a[2]);notify(lastProgress,lastMessage);}catch{};};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null){errors+=e.Data+"\n";if(errors.Length>9000)errors=errors.Substring(errors.Length-9000);}};
   lock(gate){if(cancelled)throw new OperationCanceledException();p.Start();process=p;AttachJob(p);}p.BeginOutputReadLine();p.BeginErrorReadLine();var clock=Stopwatch.StartNew();long last=-1;try{while(!p.WaitForExit(250)){if(cancelled)throw new OperationCanceledException();if(clock.ElapsedMilliseconds>12L*3600*1000)throw new TimeoutException("Tác vụ phụ đề quá 12 giờ. Có thể dừng và chạy lại.");if(clock.ElapsedMilliseconds/2000>last){last=clock.ElapsedMilliseconds/2000;notify(lastProgress,lastMessage+" · đã chạy "+(clock.ElapsedMilliseconds/1000)+"s");}}p.WaitForExit();if(cancelled)throw new OperationCanceledException();if(p.ExitCode!=0)throw new IOException("Bộ phụ đề chưa hoàn tất.\r\n"+lastMessage+"\r\n"+errors);}finally{lock(gate){if(!p.HasExited)try{p.Kill();}catch{}process=null;if(job!=IntPtr.Zero){CloseHandle(job);job=IntPtr.Zero;}}}}
 }
 public void Cancel(){lock(gate){cancelled=true;if(job!=IntPtr.Zero){CloseHandle(job);job=IntPtr.Zero;}if(process!=null)try{if(!process.HasExited)process.Kill();}catch{}}}public void Dispose(){Cancel();}
 [StructLayout(LayoutKind.Sequential)]struct BASIC {public long PerProcessUserTimeLimit,PerJobUserTimeLimit;public uint LimitFlags;public UIntPtr MinimumWorkingSetSize,MaximumWorkingSetSize;public uint ActiveProcessLimit;public UIntPtr Affinity;public uint PriorityClass,SchedulingClass;}
 [StructLayout(LayoutKind.Sequential)]struct IO {public ulong ReadOperationCount,WriteOperationCount,OtherOperationCount,ReadTransferCount,WriteTransferCount,OtherTransferCount;}
 [StructLayout(LayoutKind.Sequential)]struct LIMIT {public BASIC BasicLimitInformation;public IO IoInfo;public UIntPtr ProcessMemoryLimit,JobMemoryLimit,PeakProcessMemoryUsed,PeakJobMemoryUsed;}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern IntPtr CreateJobObject(IntPtr attr,string name);[DllImport("kernel32.dll")]static extern bool SetInformationJobObject(IntPtr job,int type,IntPtr info,uint length);[DllImport("kernel32.dll")]static extern bool AssignProcessToJobObject(IntPtr job,IntPtr process);[DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
 void AttachJob(Process p){if(Environment.OSVersion.Platform!=PlatformID.Win32NT)return;IntPtr mem=IntPtr.Zero;try{job=CreateJobObject(IntPtr.Zero,null);var limits=new LIMIT();limits.BasicLimitInformation.LimitFlags=0x2000;int size=Marshal.SizeOf(limits);mem=Marshal.AllocHGlobal(size);Marshal.StructureToPtr(limits,mem,false);if(!SetInformationJobObject(job,9,mem,(uint)size)||!AssignProcessToJobObject(job,p.Handle)){CloseHandle(job);job=IntPtr.Zero;}}catch{if(job!=IntPtr.Zero){CloseHandle(job);job=IntPtr.Zero;}}finally{if(mem!=IntPtr.Zero)Marshal.FreeHGlobal(mem);}}
}
}
